package com.yuegang.zhihui.ai.api;import com.yuegang.zhihui.ai.application.ConversationService;import com.yuegang.zhihui.ai.security.AiUserResolver;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/ai")public final class ConversationController{private final ConversationService service;private final AiUserResolver users;public ConversationController(ConversationService s,AiUserResolver u){service=s;users=u;}@GetMapping("/conversations")ApiResponse<List<ConversationView>>list(@RequestParam(defaultValue="20")int limit,HttpServletRequest r){return ok(service.list(users.resolve(r),limit),r);}@GetMapping("/conversations/{id}/messages")ApiResponse<List<MessageView>>messages(@PathVariable String id,HttpServletRequest r){return ok(service.messages(users.resolve(r),id),r);}@PostMapping("/feedback")ApiResponse<Map<String,Boolean>>feedback(@Valid @RequestBody FeedbackRequest b,HttpServletRequest r){service.feedback(users.resolve(r),b);return ok(Map.of("completed",true),r);}private static<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.success(x,TraceIdResolver.resolve(r));}}
